"use client"

import { cn } from "@/lib/utils"

interface PasswordStrengthProps {
  password: string
}

export function PasswordStrength({ password }: PasswordStrengthProps) {
  const getStrength = (pwd: string) => {
    if (!pwd) return { score: 0, label: "Vide", color: "bg-gray-200" }
    
    let score = 0
    if (pwd.length >= 8) score++
    if (/[A-Z]/.test(pwd)) score++
    if (/[0-9]/.test(pwd)) score++
    if (/[^A-Za-z0-9]/.test(pwd)) score++

    const strength = {
      0: { label: "Très faible", color: "bg-red-500" },
      1: { label: "Faible", color: "bg-red-400" },
      2: { label: "Moyen", color: "bg-yellow-500" },
      3: { label: "Fort", color: "bg-green-500" },
      4: { label: "Très fort", color: "bg-green-600" }
    }

    return { score, ...strength[score as keyof typeof strength] }
  }

  const strength = getStrength(password)

  return (
    <div className="space-y-2">
      <div className="flex justify-between text-sm">
        <span>Force du mot de passe:</span>
        <span className={cn(
          "font-medium",
          strength.score <= 1 && "text-red-600",
          strength.score === 2 && "text-yellow-600",
          strength.score >= 3 && "text-green-600"
        )}>
          {strength.label}
        </span>
      </div>
      <div className="flex space-x-1">
        {[1, 2, 3, 4].map((level) => (
          <div
            key={level}
            className={cn(
              "h-1 flex-1 rounded-full transition-all",
              level <= strength.score ? strength.color : "bg-gray-200"
            )}
          />
        ))}
      </div>
    </div>
  )
}